 setup_stmt_stat_symbols(void)
 {
-    if (stmt_stat_symbols[0] == 0) {
 #define S(s) stmt_stat_symbols[stmt_stat_sym_##s] = ID2SYM(rb_intern_const(#s))
-        S(fullscan_steps);
